// ── Kahn's Algorithm (BFS-based) — O(V+E) ─────────────────────
// graph: adjacency list { node: [neighbors...] }
function kahnTopologicalSort(graph) {
  const inDegree = {};
  const nodes = Object.keys(graph);

  // Initialise in-degree to 0
  for (const node of nodes) inDegree[node] = 0;

  // Count incoming edges
  for (const node of nodes) {
    for (const neighbor of graph[node]) {
      inDegree[neighbor] = (inDegree[neighbor] || 0) + 1;
    }
  }

  // Start with all nodes that have no prerequisites
  const queue = nodes.filter(n => inDegree[n] === 0);
  const order = [];

  while (queue.length > 0) {
    const u = queue.shift();
    order.push(u);

    for (const v of graph[u]) {
      inDegree[v]--;
      if (inDegree[v] === 0) queue.push(v);
    }
  }

  if (order.length !== nodes.length) {
    return { order: null, hasCycle: true };
  }
  return { order, hasCycle: false };
}

// Dependency graph: A must come before B, etc.
const graph = {
  A: ["C"],
  B: ["C", "D"],
  C: ["E"],
  D: ["F"],
  E: ["F"],
  F: []
};

const { order, hasCycle } = kahnTopologicalSort(graph);
console.log(order);    // ['A','B','C','D','E','F'] (one valid order)
console.log(hasCycle); // false

// ── DFS-based Topological Sort — O(V+E) ───────────────────────
function dfsTopologicalSort(graph) {
  const WHITE = 0, GREY = 1, BLACK = 2; // unvisited, in-stack, done
  const color = {};
  const stack = [];
  let hasCycle = false;

  for (const node of Object.keys(graph)) color[node] = WHITE;

  function dfs(u) {
    if (hasCycle) return;
    color[u] = GREY; // mark as 'currently being explored'

    for (const v of graph[u]) {
      if (color[v] === GREY) {
        hasCycle = true; // back edge → cycle!
        return;
      }
      if (color[v] === WHITE) dfs(v);
    }

    color[u] = BLACK; // fully explored
    stack.push(u);    // post-order: push after all successors done
  }

  for (const node of Object.keys(graph)) {
    if (color[node] === WHITE) dfs(node);
  }

  return hasCycle ? { order: null, hasCycle: true }
                  : { order: stack.reverse(), hasCycle: false };
}

// Same graph as above
const result = dfsTopologicalSort(graph);
console.log(result.order); // ['A','B','C','D','E','F'] or equivalent valid order

// Cycle detection example
const cycleGraph = { X: ["Y"], Y: ["Z"], Z: ["X"] }; // X→Y→Z→X
const bad = dfsTopologicalSort(cycleGraph);
console.log(bad.hasCycle); // true
